+// endings converted to LF, as status hashes it under core.autocrlf.
+func (w *Worktree) hashWorktreeFile(cfg *config.Config, name string, size int64, toLF bool) (plumbing.Hash, error) {
+	f, err := w.filesystem.Open(name)
+	if err != nil {
+		return plumbing.ZeroHash, err
+	}
