// reset updates the index and worktree without changing references. Checkout
// switches HEAD afterward; Reset and Pull move the current branch afterward.
func (w *Worktree) reset(opts *ResetOptions) error {
	if trace.Performance.Enabled() {
		start := time.Now()
		defer func() {
			trace.Performance.Printf("performance: %.9f s: reset_worktree", time.Since(start).Seconds())
		}()
	}

	if err := opts.Validate(w.r); err != nil {
		return err
	}

	cfg, err := w.r.Config()
	if err != nil {
		return err
	}

	if opts.Mode == MergeReset {
		unstaged, err := w.containsUnstagedChanges(cfg)
		if err != nil {
			return err
		}

		if unstaged {
			return ErrUnstagedChanges
		}
	}

	if opts.Mode == SoftReset {
		return nil
