	t, err := w.r.getTreeFromCommitHash(opts.Commit)
	if err != nil {
		return err
	}

	if len(opts.SparseDirs) > 0 && !opts.SkipSparseDirValidation {
		if !treeContainsDirs(t, opts.SparseDirs) {
			return ErrSparseResetDirectoryNotFound
		}
	}

	var trackedChanges merkletrie.Changes
	if opts.Mode == HardReset {
		// The index identifies tracked paths even when the old HEAD tree is
		// unreadable. Capture its diff before resetIndex replaces it, including
		// staged additions that must be removed when absent from the target,
		// and SkipWorktree entries, which the index must be brought to the
		// target for too.
		trackedChanges, err = w.diffTreeWithIndex(t, true)
		if err != nil {
			return err
		}
	}

	if opts.Mode == KeepReset {
		prevTree, err := w.headTree()
		if err != nil {
			return err
		}
		if err := w.checkKeepResetConflicts(prevTree, t, opts.SparseDirs, opts.Files); err != nil {
			return err
		}
		trackedChanges, err = diffTrees(prevTree, t)
		if err != nil {
			return err
		}
	}

	// Mixed resets only update the index.
	if opts.Mode == MixedReset {
		_, err := w.resetIndex(t, opts.SparseDirs, opts.Files, nil)
		return err
	}

	// The diff of the target against every index entry, from which the
	// index is built and the SkipWorktree entries the reset touches are
	// checked. A hard reset's tracked changes are that diff, so it is not
	// computed twice.
	indexChanges := trackedChanges
	if opts.Mode != HardReset {
